'use strict';
let sites=[],filter='all',favorites=new Set();
try{const saved=JSON.parse(localStorage.getItem('data2-map-favorites')||'[]');if(Array.isArray(saved))favorites=new Set(saved.filter(x=>typeof x==='string'));}catch{}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:'#';}catch{return '#';}};
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),1800);}
function render(){const q=$('#search').value.trim().toLowerCase(),shown=sites.filter(s=>(filter==='all'||s.category===filter||(filter==='favorites'&&favorites.has(s.id)))&&[s.name,s.description,s.url,...s.tags].join(' ').toLowerCase().includes(q));$('#result-count').textContent=`${shown.length} 个入口`;
$('#cards').innerHTML=shown.map(s=>`<article class="card"><div class="card-head"><div class="site-icon ${esc(s.color)}" aria-hidden="true">${esc(s.icon)}</div><div class="card-title"><h3><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a></h3><span class="domain">${esc(new URL(s.url).hostname)}</span></div><button class="favorite" data-id="${esc(s.id)}" aria-label="${favorites.has(s.id)?'取消收藏':'收藏'}${esc(s.name)}" aria-pressed="${favorites.has(s.id)}">${favorites.has(s.id)?'★':'☆'}</button></div><p class="description">${esc(s.description)}</p><div class="tags">${s.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-bottom"><div class="source-links">${s.repo?`<a class="source-link" href="${safeUrl(s.repo)}" target="_blank" rel="noopener noreferrer">⌘ ${esc(s.repoLabel||'我的源码')}</a>`:`<span class="source-link">${s.kind==='project'?'我的开源项目':'网站入口'}</span>`}${s.upstream?`<a class="source-link" href="${safeUrl(s.upstream)}" target="_blank" rel="noopener noreferrer">上游 ↗</a>`:''}</div><a class="visit" href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${s.kind==='project'?'查看项目':'访问网站'} <span>↗</span></a></div>${s.status!=='已核验'?`<span class="pending">○ ${esc(s.status)}</span>`:''}</article>`).join('');
$('#empty').hidden=shown.length>0;$('#empty-copy').textContent=filter==='favorites'&&!q?'点击网站卡片右上角的星号，把常用入口留在这里。':'换一个关键词，或试试其他分类。';document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render();}));$('#search').addEventListener('input',render);$('#reset').addEventListener('click',()=>{filter='all';$('#search').value='';render();});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable){e.preventDefault();$('#search').focus();}});
$('#cards').addEventListener('click',e=>{const b=e.target.closest('.favorite');if(!b)return;const id=b.dataset.id;if(favorites.has(id))favorites.delete(id);else favorites.add(id);let persisted=true;try{localStorage.setItem('data2-map-favorites',JSON.stringify([...favorites]));}catch{persisted=false;}render();toast(persisted?(favorites.has(id)?'已加入收藏':'已取消收藏'):'本次收藏已更新，浏览器不支持持久保存');});
fetch('/sites.json').then(r=>{if(!r.ok)throw Error('load');return r.json();}).then(data=>{sites=data;$('#site-total').textContent=sites.length;$('#nav-count').textContent=sites.length;render();}).catch(()=>{$('#result-count').textContent='目录加载失败';$('#cards').innerHTML='<p>暂时无法加载网站清单，请刷新页面重试。</p>';});
